/* @lc app=leetcode id=2935 lang=kotlin */ class Solution { fun up(mp: Array<HashMap<Int, Int>>, x: Int, d: Int) = mp.indices.forEach { b -> mp[b].merge(x shr b, d) { a, c -> a + c } } fun maximumStrongPairXor(nums: IntArray): Int = Array(20) { HashMap<Int, Int>() }.let { mp -> nums.sorted().let { a -> a.indices.fold(0 to 0) { (l, best), r -> up(mp, a[r], 1).let { generateSequence(l) { it + 1 }.takeWhile { 2 * a[it] < a[r] }.onEach { up(mp, a[it], -1) }.count().let { c -> (l + c).let { nl -> (19 downTo 0).fold(0 to 0) { (pre, res), b -> (pre shl 1 or ((a[r] shr b and 1) xor 1)).let { want -> if ((mp[b][want] ?: 0) > 0) want to (res or (1 shl b)) else (pre shl 1 or (a[r] shr b and 1)) to res } }.second.let { x -> nl to maxOf(best, x) } } } } }.second } } }